import java.util.*;

public class Solution {
    static class Trie {
        private static class Node {
            Node[] filhos = new Node[26];
            boolean fim;
        }

        private final Node raiz = new Node();
        private int nos;

        void inserir(String p) {
            Node n = raiz;
            for (char c : p.toCharArray()) {
                int i = c - 'a';
                if (n.filhos[i] == null) {
                    n.filhos[i] = new Node();
                    nos++;
                }
                n = n.filhos[i];
            }
            n.fim = true;
        }

        private Node achar(String s) {
            Node n = raiz;
            for (char c : s.toCharArray()) {
                n = n.filhos[c - 'a'];
                if (n == null) return null;
            }
            return n;
        }

        boolean contem(String p) {
            Node n = achar(p);
            return n != null && n.fim; // sem `fim`, todo prefixo pareceria uma palavra
        }

        boolean comecaCom(String prefixo) { return achar(prefixo) != null; }

        List<String> autocomplete(String prefixo) {
            List<String> out = new ArrayList<>();
            Node n = achar(prefixo);
            if (n != null) coletar(n, new StringBuilder(prefixo), out);
            return out;
        }

        // DFS em ordem de letra → resultado já sai em ordem alfabética.
        private void coletar(Node n, StringBuilder sb, List<String> out) {
            if (n.fim) out.add(sb.toString());
            for (int i = 0; i < 26; i++) {
                if (n.filhos[i] == null) continue;
                sb.append((char) ('a' + i));
                coletar(n.filhos[i], sb, out);
                sb.deleteCharAt(sb.length() - 1);
            }
        }

        boolean remover(String p) {
            if (!contem(p)) return false;
            remover(raiz, p, 0);
            return true;
        }

        // Devolve true se o nó ficou inútil (não é fim e não tem filhos) e pode ser podado.
        private boolean remover(Node n, String p, int d) {
            if (d == p.length()) {
                n.fim = false;
            } else {
                int i = p.charAt(d) - 'a';
                if (remover(n.filhos[i], p, d + 1)) {
                    n.filhos[i] = null;
                    nos--;
                }
            }
            if (n.fim) return false;
            for (Node f : n.filhos) if (f != null) return false;
            return true;
        }

        int nos() { return nos; }
    }
}

