import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static Solution.Trie trie(String... ps) {
        var t = new Solution.Trie();
        for (String p : ps) t.inserir(p);
        return t;
    }

    @Test void contemExigeFim() {
        var t = trie("casa", "casamento", "cal");
        assertTrue(t.contem("casa"));
        assertFalse(t.contem("cas"));
        assertTrue(t.comecaCom("cas"));
        assertFalse(t.comecaCom("x"));
    }

    @Test void autocompleteOrdenado() {
        var t = trie("casa", "cal", "casamento", "carro", "dado");
        assertEquals(List.of("cal", "carro", "casa", "casamento"), t.autocomplete("ca"));
        assertEquals(List.of("casa", "casamento"), t.autocomplete("casa"));
        assertEquals(List.of(), t.autocomplete("z"));
    }

    @Test void removerPoda() {
        var t = trie("casa", "casamento");
        assertEquals(9, t.nos());
        assertTrue(t.remover("casamento"));
        assertEquals(4, t.nos());
        assertTrue(t.contem("casa"));
        assertFalse(t.remover("casamento"));
        assertTrue(t.remover("casa"));
        assertEquals(0, t.nos());
    }

    @Test void removerPrefixoMantemOsNos() {
        var t = trie("casa", "casamento");
        assertTrue(t.remover("casa"));
        assertFalse(t.contem("casa"));
        assertTrue(t.contem("casamento"));
        assertEquals(9, t.nos());
    }
}
